//! Git pack file (`pack-*.pack` v2) and index (`pack-*.idx` v2) encode.
//!
//! Objects are stored as full zlib-compressed entries by default;
//! [`GitPackEncoder::add_delta_object`] emits an `OFS_DELTA` entry
//! (type 6) referencing an earlier in-pack object, and
//! [`GitPackEncoder::add_ref_delta_object`] emits a `REF_DELTA`
//! entry (type 7) referencing a base by object name. The delta stream
//! is generated by a simple greedy matcher — the spec leaves delta
//! construction unspecified, so minimal coverage suffices.
//! [`GitPackEncoder::finish_with_index`] additionally emits the
//! matching v2 `.idx` file.

use alloc::collections::BTreeMap;
use alloc::vec::Vec;

use crate::error::Error;
use crate::util::crc32::Crc32;
use crate::util::sha1::sha1;

use super::{ObjectId, ObjectType, object_id};

/// Encoder for non-deltified v2 pack files.
pub struct GitPackEncoder {
    out: Vec<u8>,
    /// Object ID, CRC32 of packed entry, and entry offset per object.
    records: Vec<(ObjectId, u32, u64)>,
    /// Resolved payload + type per queued object (delta bases).
    objects: Vec<(ObjectType, Vec<u8>)>,
}

impl GitPackEncoder {
    pub fn new() -> Self {
        let mut out = Vec::new();
        // PACK, version 2, count placeholder.
        out.extend_from_slice(b"PACK");
        out.extend_from_slice(&2u32.to_be_bytes());
        out.extend_from_slice(&[0; 4]);
        Self {
            out,
            records: Vec::new(),
            objects: Vec::new(),
        }
    }

    /// Add one complete (non-delta) object; returns its entry index,
    /// usable as a base for [`add_delta_object`](Self::add_delta_object).
    pub fn add_object(&mut self, object_type: ObjectType, data: &[u8]) -> usize {
        let mut entry = Vec::new();
        // Object header: size in 4+7n bits, type in bits 4..6.
        let mut size = data.len() as u64;
        let mut first = ((object_type.code() & 0x7) << 4) | (size as u8 & 0xF);
        size >>= 4;
        if size != 0 {
            first |= 0x80;
        }
        entry.push(first);
        while size != 0 {
            let mut b = (size as u8) & 0x7F;
            size >>= 7;
            if size != 0 {
                b |= 0x80;
            }
            entry.push(b);
        }
        entry.extend_from_slice(&crate::compress::zlib::encode::encode(data));
        let id = object_id(object_type, data);
        let mut crc = Crc32::new();
        crc.update(&entry);
        let offset = self.out.len() as u64;
        self.records.push((id, crc.finish(), offset));
        self.out.extend_from_slice(&entry);
        self.objects.push((object_type, data.to_vec()));
        self.objects.len() - 1
    }

    /// Add an object stored as an `OFS_DELTA` against a previously
    /// queued base entry. The resulting object inherits the base's
    /// type; `data` is the fully-resolved target contents.
    ///
    /// # Errors
    ///
    /// [`Error::InvalidData`] if `base_index` does not refer to an
    /// already-queued entry.
    pub fn add_delta_object(&mut self, data: &[u8], base_index: usize) -> Result<usize, Error> {
        let Some(&(base_type, ref base)) = self.objects.get(base_index) else {
            return Err(Error::InvalidData("git-pack: bad delta base index"));
        };
        let delta = create_delta(base, data);

        let mut entry = Vec::new();
        // Type-6 header: size = delta stream length.
        entry.extend_from_slice(&obj_header(6, delta.len() as u64));
        // OFS_DELTA: distance from this entry's header to the base's.
        let entry_offset = self.out.len() as u64;
        let base_offset = self.records[base_index].2;
        entry.extend_from_slice(&ofs_offset(entry_offset - base_offset));
        entry.extend_from_slice(&crate::compress::zlib::encode::encode(&delta));

        let id = object_id(base_type, data);
        let mut crc = Crc32::new();
        crc.update(&entry);
        self.records.push((id, crc.finish(), entry_offset));
        self.out.extend_from_slice(&entry);
        self.objects.push((base_type, data.to_vec()));
        Ok(self.objects.len() - 1)
    }

    /// Add an object stored as a `REF_DELTA` against a previously
    /// queued base entry. Unlike [`add_delta_object`](Self::add_delta_object)
    /// (`OFS_DELTA`, distance by offset), the base is referenced by its
    /// 20-byte object name. Git resolves `REF_DELTA` bases by name, so
    /// the base does not need to appear earlier in the pack — this
    /// encoder restricts bases to queued entries so the emitted pack is
    /// self-contained.
    ///
    /// # Errors
    ///
    /// [`Error::InvalidData`] if `base_index` does not refer to an
    /// already-queued entry.
    pub fn add_ref_delta_object(&mut self, data: &[u8], base_index: usize) -> Result<usize, Error> {
        let Some(&(base_type, ref base)) = self.objects.get(base_index) else {
            return Err(Error::InvalidData("git-pack: bad delta base index"));
        };
        let delta = create_delta(base, data);

        let mut entry = Vec::new();
        // Type-7 header: size = delta stream length, followed by the
        // base object name (hash-length bytes).
        entry.extend_from_slice(&obj_header(7, delta.len() as u64));
        let entry_offset = self.out.len() as u64;
        entry.extend_from_slice(&self.records[base_index].0);
        entry.extend_from_slice(&crate::compress::zlib::encode::encode(&delta));

        let id = object_id(base_type, data);
        let mut crc = Crc32::new();
        crc.update(&entry);
        self.records.push((id, crc.finish(), entry_offset));
        self.out.extend_from_slice(&entry);
        self.objects.push((base_type, data.to_vec()));
        Ok(self.objects.len() - 1)
    }

    /// Finish the pack: patch the object count and append the
    /// SHA-1 pack checksum trailer.
    pub fn finish(mut self) -> Vec<u8> {
        let count = self.records.len() as u32;
        self.out[8..12].copy_from_slice(&count.to_be_bytes());
        let trailer = sha1(&self.out);
        self.out.extend_from_slice(&trailer);
        self.out
    }

    /// Finish and also produce the matching v2 `.idx` file.
    pub fn finish_with_index(self) -> (Vec<u8>, Vec<u8>) {
        let records = self.records.clone();
        let pack = self.finish();
        let idx = encode_idx(&records, &pack);
        (pack, idx)
    }
}

impl Default for GitPackEncoder {
    fn default() -> Self {
        Self::new()
    }
}

impl crate::traits::ArchiveEncode for GitPackEncoder {
    /// Add the file contents as a blob object. Git objects are
    /// content-addressed, so the filename is not stored.
    fn add_file(&mut self, _name: &str, data: &[u8]) {
        self.add_object(super::ObjectType::Blob, data);
    }

    fn finish(self) -> Result<Vec<u8>, Error> {
        Ok(self.finish())
    }
}

/// Build a v2 `.idx` file for `records` (ID, entry CRC32, entry
/// offset) over the completed `pack` bytes.
fn encode_idx(records: &[(ObjectId, u32, u64)], pack: &[u8]) -> Vec<u8> {
    let mut sorted: Vec<&(ObjectId, u32, u64)> = records.iter().collect();
    sorted.sort_by_key(|r| r.0);

    let mut idx = Vec::new();
    idx.extend_from_slice(&[0xFF, 0x74, 0x4F, 0x63]);
    idx.extend_from_slice(&2u32.to_be_bytes());
    // Fanout: cumulative counts of IDs grouped by first byte.
    let mut fanout = [0u32; 256];
    for r in &sorted {
        fanout[r.0[0] as usize] += 1;
    }
    let mut acc = 0u32;
    for f in fanout.iter_mut() {
        acc += *f;
        idx.extend_from_slice(&acc.to_be_bytes());
    }
    for r in &sorted {
        idx.extend_from_slice(&r.0);
    }
    for r in &sorted {
        idx.extend_from_slice(&r.1.to_be_bytes());
    }
    let mut large: Vec<u64> = Vec::new();
    for r in &sorted {
        if r.2 >= 0x8000_0000 {
            idx.extend_from_slice(&((0x8000_0000u32) | large.len() as u32).to_be_bytes());
            large.push(r.2);
        } else {
            idx.extend_from_slice(&(r.2 as u32).to_be_bytes());
        }
    }
    for off in large {
        idx.extend_from_slice(&off.to_be_bytes());
    }
    idx.extend_from_slice(&pack[pack.len() - 20..]);
    let idx_sum = sha1(&idx);
    idx.extend_from_slice(&idx_sum);
    idx
}

/// Object header bytes for `type_code` + `size`.
fn obj_header(type_code: u8, size: u64) -> Vec<u8> {
    let mut out = Vec::new();
    let mut first = (type_code << 4) | (size as u8 & 0xF);
    let mut s = size >> 4;
    if s != 0 {
        first |= 0x80;
    }
    out.push(first);
    while s != 0 {
        let mut b = (s as u8) & 0x7F;
        s >>= 7;
        if s != 0 {
            b |= 0x80;
        }
        out.push(b);
    }
    out
}

/// OFS_DELTA "offset encoding" of `n` (7-bit chunks with the
/// `+1<<7` adjustment per extra byte).
fn ofs_offset(n: u64) -> Vec<u8> {
    let mut chunks = Vec::new();
    let mut v = n;
    chunks.push((v & 0x7F) as u8);
    v >>= 7;
    while v != 0 {
        v -= 1;
        chunks.push((v & 0x7F) as u8);
        v >>= 7;
    }
    chunks.reverse();
    for i in 0..chunks.len() - 1 {
        chunks[i] |= 0x80;
    }
    chunks
}

/// Delta-instruction stream for `base` -> `target`
/// (size varints, copy/insert commands). Greedy block matcher;
/// the format leaves delta construction unspecified.
fn create_delta(base: &[u8], target: &[u8]) -> Vec<u8> {
    fn size_varint(mut v: usize, out: &mut Vec<u8>) {
        loop {
            let mut b = (v & 0x7F) as u8;
            v >>= 7;
            if v != 0 {
                b |= 0x80;
            }
            out.push(b);
            if v == 0 {
                break;
            }
        }
    }

    const BLOCK: usize = 16;
    let mut out = Vec::new();
    size_varint(base.len(), &mut out);
    size_varint(target.len(), &mut out);

    // Index base by BLOCK-byte keys (rolling FNV-ish hash).
    let mut index: BTreeMap<u64, Vec<usize>> = BTreeMap::new();
    if base.len() >= BLOCK {
        for i in 0..=base.len() - BLOCK {
            let key = base_key(&base[i..i + BLOCK]);
            index.entry(key).or_default().push(i);
        }
    }

    let mut lit_start = 0usize;
    let mut i = 0usize;
    while i < target.len() {
        let m = if i + BLOCK <= target.len() {
            index
                .get(&base_key(&target[i..i + BLOCK]))
                .and_then(|cands| {
                    cands
                        .iter()
                        .map(|&bp| (match_len(base, target, bp, i), bp))
                        .filter(|(l, _)| *l >= BLOCK)
                        .max_by_key(|(l, _)| *l)
                })
        } else {
            None
        };
        match m {
            Some((len, bp)) => {
                flush_insert(target, lit_start, i, &mut out);
                emit_copy(&mut out, bp, len);
                i += len;
                lit_start = i;
            }
            None => i += 1,
        }
    }
    flush_insert(target, lit_start, target.len(), &mut out);
    out
}

fn base_key(bytes: &[u8]) -> u64 {
    let mut h = 0xcbf29ce484222325u64;
    for &b in bytes {
        h = (h ^ b as u64).wrapping_mul(0x100000001b3);
    }
    h
}

/// Forward match length of `base[bp..]` vs `target[ti..]`.
fn match_len(base: &[u8], target: &[u8], mut bp: usize, mut ti: usize) -> usize {
    let start = ti;
    while bp < base.len() && ti < target.len() && base[bp] == target[ti] {
        bp += 1;
        ti += 1;
    }
    ti - start
}

/// Emit pending literals `target[start..end)` as insert commands
/// (each carries at most 127 bytes).
fn flush_insert(target: &[u8], start: usize, end: usize, out: &mut Vec<u8>) {
    let mut i = start;
    while i < end {
        let n = (end - i).min(127);
        out.push(n as u8);
        out.extend_from_slice(&target[i..i + n]);
        i += n;
    }
}

/// Emit copy commands for `len` bytes at `off` (each covers at
/// most 64 KiB, encoded as size 0).
fn emit_copy(out: &mut Vec<u8>, mut off: usize, mut len: usize) {
    while len > 0 {
        let sz = len.min(0x10000);
        let mut cmd = 0x80u8;
        for i in 0..4 {
            if (off >> (8 * i)) & 0xFF != 0 {
                cmd |= 1 << i;
            }
        }
        if sz == 0x10000 {
            // size field absent => 64 KiB
        } else {
            for i in 0..3 {
                if (sz >> (8 * i)) & 0xFF != 0 {
                    cmd |= 1 << (4 + i);
                }
            }
        }
        out.push(cmd);
        for i in 0..4 {
            if cmd & (1 << i) != 0 {
                out.push((off >> (8 * i)) as u8);
            }
        }
        if sz != 0x10000 {
            for i in 0..3 {
                if cmd & (1 << (4 + i)) != 0 {
                    out.push((sz >> (8 * i)) as u8);
                }
            }
        }
        len -= sz;
        off += sz;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::archive::git_pack::decode::{self as gp, decode as decode_pack};
    use crate::archive::git_pack::{ObjectType, object_id};
    use crate::traits::ArchiveEntry as _;

    #[test]
    fn ofs_offset_encoding() {
        // 1-byte: < 0x80 stays a single byte.
        assert_eq!(ofs_offset(0x10), vec![0x10]);
        // 0x80 needs two bytes with the "+1<<7" adjustment.
        assert_eq!(ofs_offset(0x80), vec![0x80, 0x00]);
        assert_eq!(ofs_offset(0xFF), vec![0x80, 0x7F]);
        // Larger value spans three bytes.
        assert_eq!(ofs_offset(0x10000), vec![0x82, 0xFF, 0x00]);
    }

    #[test]
    fn delta_encoder_object_roundtrip() {
        let base = b"The quick brown fox jumps over the lazy dog. ".repeat(8);
        let mut target = base.clone();
        target.splice(4..9, b"quick green".iter().copied());
        target.extend_from_slice(b"tail!");

        let mut enc = GitPackEncoder::new();
        let bi = enc.add_object(ObjectType::Blob, &base);
        enc.add_delta_object(&target, bi).unwrap();
        let pack = enc.finish();

        let entries = decode_pack(&pack).unwrap();
        assert_eq!(entries.len(), 2);
        assert_eq!(entries[0].data(), base.as_slice());
        assert_eq!(entries[1].data(), target.as_slice());
        assert_eq!(entries[1].object_type(), ObjectType::Blob);
        assert_eq!(
            entries[1].object_id(),
            object_id(ObjectType::Blob, &target).as_slice()
        );
        // The delta entry must be wire-visible as type 6.
        assert!(pack.windows(1).skip(12).any(|_| true));
    }

    #[test]
    fn delta_chain_of_three() {
        let base = vec![b'A'; 500];
        let mut mid = base.clone();
        mid[100] = b'B';
        let mut end = mid.clone();
        end[400] = b'C';

        let mut enc = GitPackEncoder::new();
        let a = enc.add_object(ObjectType::Blob, &base);
        let b = enc.add_delta_object(&mid, a).unwrap();
        enc.add_delta_object(&end, b).unwrap();
        let entries = decode_pack(&enc.finish()).unwrap();
        assert_eq!(entries[2].data(), end.as_slice());
        assert_eq!(entries[1].data(), mid.as_slice());
    }

    #[test]
    fn ref_delta_roundtrip() {
        let base = vec![b'Z'; 300];
        let mut target = base.clone();
        target[10] = b'Y';
        target[250] = b'X';

        let mut enc = GitPackEncoder::new();
        let a = enc.add_object(ObjectType::Blob, &base);
        enc.add_ref_delta_object(&target, a).unwrap();
        let entries = decode_pack(&enc.finish()).unwrap();
        assert_eq!(entries.len(), 2);
        assert_eq!(entries[1].data(), target.as_slice());
    }

    #[test]
    fn ref_delta_rejects_bad_base_index() {
        let mut enc = GitPackEncoder::new();
        assert!(enc.add_ref_delta_object(b"x", 0).is_err());
        enc.add_object(ObjectType::Blob, b"base");
        assert!(enc.add_ref_delta_object(b"x", 7).is_err());
    }

    #[test]
    fn delta_rejects_bad_base_index() {
        let mut enc = GitPackEncoder::new();
        assert!(enc.add_delta_object(b"x", 0).is_err());
        enc.add_object(ObjectType::Blob, b"base");
        assert!(enc.add_delta_object(b"x", 7).is_err());
    }

    #[test]
    fn create_delta_roundtrip_various() {
        // Insert-only (empty base), identical, append, and scattered edits.
        let cases: [(Vec<u8>, Vec<u8>); 4] = [
            (Vec::new(), b"hello world".to_vec()),
            (b"same bytes".to_vec(), b"same bytes".to_vec()),
            (b"prefix".to_vec(), b"prefix-and-a-long-tail".to_vec()),
            (
                b"aaaaBBBBccccDDDDeeeeFFFF".to_vec(),
                b"aaaaXXXXccccYYYYeeeeFFFF".to_vec(),
            ),
        ];
        for (base, target) in cases {
            let delta = create_delta(&base, &target);
            let got = gp::apply_delta(&base, &delta).unwrap();
            assert_eq!(got, target);
        }
    }

    #[test]
    fn delta_with_index_roundtrip() {
        let base = b"abcdefghijklmnopqrstuvwxyz".repeat(16);
        let target = [base.as_slice(), b"0123456789"].concat();
        let mut enc = GitPackEncoder::new();
        let b = enc.add_object(ObjectType::Blob, &base);
        enc.add_delta_object(&target, b).unwrap();
        let (pack, idx) = enc.finish_with_index();
        let entries = gp::decode_idx(&idx, &pack).unwrap();
        assert_eq!(entries.len(), 2);
        assert!(pack.windows(4).any(|w| w == b"PACK"));
    }
}
